<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: #11182b;
        --panel-strong: #17213a;
        --text: #f7f8fc;
        --muted: #c7d0e3;
        --accent: #7cc7ff;
        --accent-strong: #a6dcff;
        --border: #40506d;
        --field-bg: #0f1728;
        --focus: #ffd166;
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-width: 320px;
        margin: 0;
        font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
        color: var(--text);
        background:
          radial-gradient(circle at top left, #244364 0, transparent 32rem),
          linear-gradient(135deg, var(--bg), #070a13 62%);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        color: #07111f;
        background: var(--focus);
        border-radius: 999px;
        transform: translateY(-150%);
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #07111f;
      }

      .page-shell {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      main {
        width: min(100%, 44rem);
      }

      .support-card {
        overflow: hidden;
        border: 1px solid var(--border);
        border-radius: 1.5rem;
        background: linear-gradient(180deg, var(--panel), #0d1425);
        box-shadow: 0 1.5rem 4rem #02050d;
      }

      .card-header {
        padding: clamp(1.5rem, 5vw, 3rem);
        background: linear-gradient(135deg, var(--panel-strong), #11182b);
        border-bottom: 1px solid var(--border);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent-strong);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 7vw, 3.75rem);
        line-height: 1;
        overflow-wrap: anywhere;
      }

      .intro {
        max-width: 36rem;
        margin: 1rem 0 0;
        color: var(--muted);
        font-size: 1.0625rem;
      }

      form {
        display: grid;
        gap: 1.25rem;
        padding: clamp(1.5rem, 5vw, 3rem);
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
        min-width: 0;
      }

      label {
        color: var(--text);
        font-weight: 700;
      }

      .required-note,
      .helper-text {
        color: var(--muted);
        font-size: 0.9375rem;
      }

      .required-marker {
        color: var(--accent-strong);
        font-weight: 800;
      }

      input {
        width: 100%;
        min-height: 3.25rem;
        padding: 0.85rem 1rem;
        color: var(--text);
        background: var(--field-bg);
        border: 1px solid var(--border);
        border-radius: 0.875rem;
        font: inherit;
        transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
      }

      input::placeholder {
        color: #9aa8bf;
      }

      input:hover {
        border-color: #6f85aa;
      }

      input:focus {
        border-color: var(--focus);
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #6f551d;
      }

      button {
        width: 100%;
        min-height: 3.35rem;
        margin-top: 0.5rem;
        padding: 0.9rem 1.25rem;
        color: #061526;
        background: linear-gradient(135deg, var(--accent-strong), #6ab8ff);
        border: 0;
        border-radius: 999px;
        font: inherit;
        font-weight: 800;
        cursor: pointer;
        transition: transform 160ms ease, box-shadow 160ms ease;
      }

      button:hover {
        transform: translateY(-1px);
        box-shadow: 0 0.85rem 1.5rem #02050d;
      }

      button:focus {
        outline: 3px solid transparent;
        box-shadow: 0 0 0 4px #6f551d;
      }

      @media (max-width: 30rem) {
        .page-shell {
          padding: 1rem;
        }

        .support-card {
          border-radius: 1rem;
        }
      }

      @media (forced-colors: active) {
        body,
        .support-card,
        .card-header,
        input,
        button,
        .skip-link {
          color: CanvasText;
          background: Canvas;
          border-color: CanvasText;
          box-shadow: none;
        }

        button {
          border: 2px solid ButtonBorder;
          color: ButtonText;
        }

        input:focus,
        button:focus,
        .skip-link:focus {
          outline: 3px solid CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const fields = [
        {
          id: "full-name",
          label: "Full name",
          type: "text",
          name: "fullName",
          autocomplete: "name",
          placeholder: "Jordan Lee",
          required: true
        },
        {
          id: "email-address",
          label: "Email address",
          type: "email",
          name: "email",
          autocomplete: "email",
          placeholder: "jordan@example.com",
          required: true
        },
        {
          id: "phone-number",
          label: "Phone number",
          type: "tel",
          name: "phone",
          autocomplete: "tel",
          placeholder: "+1 555 123 4567",
          helperText: "Use international format when possible, such as +1 555 123 4567."
        }
      ];

      function Field({ id, label, type, name, autocomplete, placeholder, required, helperText }) {
        const helperId = helperText ? `${id}-helper` : "";

        return `
          <div class="form-field">
            <label for="${id}">
              ${label}${required ? ' <span class="required-marker" aria-hidden="true">*</span>' : ""}
            </label>
            <input
              id="${id}"
              name="${name}"
              type="${type}"
              autocomplete="${autocomplete}"
              placeholder="${placeholder}"
              ${required ? "required aria-required=\"true\"" : ""}
              ${helperId ? `aria-describedby="${helperId}"` : ""}
            >
            ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
          </div>
        `;
      }

      function SupportContactForm() {
        return `
          <section class="support-card" aria-labelledby="support-heading">
            <div class="card-header">
              <p class="eyebrow">Support</p>
              <h1 id="support-heading">How can we help?</h1>
              <p class="intro">
                Send our support team your contact details and we will follow up with the next available specialist.
              </p>
            </div>
            <form action="#" method="post" novalidate>
              <p class="required-note"><span class="required-marker" aria-hidden="true">*</span> Required fields</p>
              ${fields.map(Field).join("")}
              <button type="submit">Submit request</button>
            </form>
          </section>
        `;
      }

      function App() {
        return `
          <div class="page-shell">
            <main id="main-content">
              ${SupportContactForm()}
            </main>
          </div>
        `;
      }

      document.getElementById("root").innerHTML = App();
    </script>
  </body>
</html>
